def get_date(start_time_str,end_time_str):    #获取输入时间段内的日期
    dates=[]
    start_time = datetime.strptime(start_time_str,'%Y-%M-%d') #把字符串转化为日期
    end_time = datetime.strptime(end_time_str,'%Y-%M-%d')
    date_diff = (end_time - start_time).days   #计算日期差

    for i in range(date_diff + 1):
        data_date = start_time + timedelta(days=i)   #递增日期
        dates.append(data_date.strftime('%Y-%M-%d'))   #把日期增加到列表
    return dates

