    data = {"lt": "", "execution": "", "_eventId": "submit", "userLocale": "zh_CN", "username": "27380",
            "password": "123", "rememberMe": "true"}
    header = {
        "Content-Type": "application/x-www-form-urlencoded",
        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8,application/signed-exchange;v=b3;q=0.7",
        "Referer": "http://10.79.5.175:8080/dpas/login"
    }
    r = requests.post(url=url,data=data,headers=header)
    res_cookie = r.headers['Set-Cookie']
    a = res_cookie.split(';')[0]
    b = res_cookie.split(';')[-6].split(',')[1][1:]
    cookie = a+';'+b
    return cookie
