    def common(self):
        resulr = ''
        try:
            departure = self.lineEdit.text()
            destination = self.lineEdit_2.text()
            start_time = self.lineEdit_3.text()
            end_time = self.lineEdit_4.text()
            listx = self.lineEdit_5.text()

            list1 = ['F']  # 头等舱
            list2 = ['J', 'C', 'D', 'I', 'O']  # 公务舱
            list3 = ['W', 'S']  # 明珠经济舱
            list4 = ['Y', 'P', 'B', 'M', 'H', 'K', 'U', 'A', 'L', 'Q', 'E', 'V', 'Z', 'T', 'N', 'R', 'G', 'X']  # 经济舱
            list5 = ['F', 'J', 'C', 'D', 'I', 'O', 'W', 'S', 'Y', 'P', 'B', 'M', 'H', 'K', 'U', 'A', 'L', 'Q', 'E', 'V',
                     'Z', 'T', 'N', 'R', 'G', 'X']

            date_1 = get_date(start_time, end_time)
            cookies = get_cookies()
            for z in range(len(date_1)):
                url_1 = 'http://10.79.5.175:8080/dpas/pages/publish/page'
                data_2 = {"params['departure']": departure, "params['destination']": destination,
                          "params['flightDate']": date_1[z],
                          "params['checkType']": "1", "page.pageNo": '1', "page.pageSize": '10'}
                hearder_1 = {"Accept": "text/html, */*; q=0.01", "Cookie": cookies,
                             "Referer": "http://10.79.5.175:8080/dpas/doLogin"}
                res = requests.get(url=url_1, params=data_2, headers=hearder_1)
                b = 'gn:middle;">(.*?)</td>'
                c = re.findall(b, res.text)
                list_cw = []
                list_m = []
                list_data = []
                for r in c:
                    try:
                        if r in list5:
                            list_cw.append(r)
                        list_m.append(int(r))
                    except:
                        pass

                for n in range(len(list_cw)):
                    list_data.append(list_cw[n] + ':' + str(list_m[n]))

                list_fina = []
                if listx == '1':
                    list_sel = list1
                elif listx == '2':
                    list_sel = list2
                elif listx == '3':
                    list_sel = list3
                elif listx == '4':
                    list_sel = list4
                elif listx == '5':
                    list_sel = list5

                for m in list_data:
                    if m[0] in list_sel:
                        list_fina.append(m[2:])

                for j in range(len(list_fina) - 1):
                    if int(list_fina[j]) > int(list_fina[j + 1]):
                        # resulr += 'pass\n'
                        pass

                    else:

                        resulr += '航段：' + departure + '-' + destination + ',日期：' + date_1[z] + ',' + str(
                            list_fina[j]) + '倒挂' + str(list_fina[j + 1])+'\n'
                        break
                if resulr == '':
                    resulr = '您查询的数据无倒挂'
                    self.plainTextEdit.setPlainText(str(resulr))
                else:
                    self.plainTextEdit.setPlainText(str(resulr))

        except Exception as e:
            print(e)

